 select distinct on(m.release_code,m.set_id,m.local_id,m.holo) m.*,c.id,c.nome,c.sigla,c.lingua from manifest m join public.cards c
 on c.lingua='INT' and lower(split_part(c.sigla,'@',1))=m.set_id
 and(public.catalog_number(coalesce(nullif(c.source_local_id,''),c.numero::text))=public.catalog_number(m.local_id)
 or m.set_id='swshp' and c.source_local_id is null and c.numero::text=regexp_replace(m.local_id,'^SWSH',''))
 and public.catalog_normalize(c.nome)=public.catalog_normalize(m.name)
 order by m.release_code,m.set_id,m.local_id,m.holo,(c.source_uid like 'tcgdex:%') desc nulls last,c.id
)
insert into public.catalog_search_entries(entry_key,card_id,release_code,release_year,collector_number,denominator,name,set_code,language,tags,facts,source_url,source_payload,verification,label,search_text)
select m.release_code||':'||m.id||':'||(case when holo then 'holo' else 'normal' end),m.id,m.release_code,year,public.catalog_number(local_id),nullif(denominator,''),m.nome,m.sigla,m.lingua,
 case when holo then array['family:'||family,'stamp:'||stamp,'finish:holo','visual:shiny'] else array['family:'||family,'stamp:'||stamp,'finish:normal'] end,
 public.catalog_base_facts(c)||jsonb_build_object('shiny',m.holo,'extra_mark',true)||(case when family='trick-or-trade' then '{"mark_pumpkin_like":true}'::jsonb else '{}'::jsonb end),source,payload,'source',
 release_name||' · '||(case when holo then 'Holo' else 'Non-Holo' end)||' · '||(case when family='trick-or-trade' then 'Timbro zucca Pikachu' else 'Logo Play! Pokémon' end),public.catalog_normalize(m.nome||' '||m.sigla||' '||release_name||' '||year)
from matched m join public.cards c on c.id=m.id
on conflict(entry_key) do nothing;
